import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Fused kernel to compute min over dim=1 and then add bias
fused_min_bias_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_min_bias_kernel(const float* x, const float* bias, float* out, int N, int C) {
    int n = blockIdx.x;
    if(n >= N) return;

    // Find row-wise minimum
    float min_val = x[n*C + 0];
    for(int c = 1; c < C; c++){
        float val = x[n*C + c];
        if(val < min_val) {
            min_val = val;
        }
    }

    // Add bias to the min value for each channel
    for(int c = threadIdx.x; c < C; c += blockDim.x) {
        out[n*C + c] = min_val + bias[c];
    }
}

torch::Tensor fused_min_bias_cuda(torch::Tensor x, torch::Tensor bias){
    // x has shape [N, C], bias has shape [C]
    int N = x.size(0);
    int C = x.size(1);

    auto out = torch::empty_like(x);

    dim3 blocks(N);
    dim3 threads(256);

    fused_min_bias_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        N,
        C
    );

    return out;
}
"""

fused_min_bias_cpp_source = r"torch::Tensor fused_min_bias_cuda(torch::Tensor x, torch::Tensor bias);"

# Build the fused operator
fused_min_bias = load_inline(
    name="fused_min_bias",
    cpp_sources=fused_min_bias_cpp_source,
    cuda_sources=fused_min_bias_source,
    functions=["fused_min_bias_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model that performs GEMM, GroupNorm, then a fused custom kernel
    to compute the row-wise minimum and add bias.
    """
    def __init__(self, in_features, out_features, num_groups, bias_shape):
        super(ModelNew, self).__init__()
        self.gemm = nn.Linear(in_features, out_features)
        self.group_norm = nn.GroupNorm(num_groups, out_features)
        # Match original bias shape but internally we'll flatten before the fused kernel
        self.bias = nn.Parameter(torch.randn(bias_shape))

        # Expose the fused function
        self.fused_min_bias = fused_min_bias

    def forward(self, x):
        x = self.gemm(x)
        x = self.group_norm(x)
        # Apply fused min + bias
        # Shape after gemm/groupnorm: [N, out_features]
        x = self.fused_min_bias.fused_min_bias_cuda(x, self.bias.view(-1))
        # Reshape to [N, out_features, 1, 1] to match original final shape
        x = x.view(x.size(0), -1, 1, 1)
        return x
